<script setup>
import { onMounted,ref } from 'vue';import { api } from '../api'
const data=ref({items:[],page:0,size:20,total:0}),error=ref('');async function load(page=0){try{data.value=await api(`/api/practices/history?page=${page}&size=20`)}catch(e){error.value=e.message}}onMounted(()=>load())
</script>
<template><div class="practice-shell"><header class="practice-top"><div><span class="practice-kicker">PRACTICE HISTORY</span><h1 class="practice-title">练习历史</h1></div><RouterLink to="/">返回首页</RouterLink></header><div class="p-card"><p v-if="error" class="p-error">{{error}}</p><p v-if="!data.items.length" class="p-muted">还没有已提交练习。</p><table v-else class="p-table"><thead><tr><th>提交时间</th><th>题量</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="p in data.items" :key="p.id"><td>{{new Date(p.submittedAt).toLocaleString()}}</td><td>{{p.questionCount}}</td><td>{{p.status}}</td><td><RouterLink :to="`/practice/${p.id}/result`">查看结果</RouterLink></td></tr></tbody></table><div class="p-actions" style="margin-top:18px"><button class="p-secondary" :disabled="data.page===0" @click="load(data.page-1)">上一页</button><span>第 {{data.page+1}} / {{Math.max(1,Math.ceil(data.total/data.size))}} 页</span><button class="p-secondary" :disabled="(data.page+1)*data.size>=data.total" @click="load(data.page+1)">下一页</button></div></div></div></template>
